import React, { useEffect, useRef } from 'react';
import { Position } from '../../types/game';

interface HeroSpriteProps {
  spriteSheet: string;
  position: Position;
  isMoving: boolean;
  direction: 'up' | 'down' | 'left' | 'right';
  scale?: number;
}

const HeroSprite: React.FC<HeroSpriteProps> = ({
  spriteSheet,
  position,
  isMoving,
  direction,
  scale = 1
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const frameRef = useRef(0);
  const lastUpdateRef = useRef(0);

  const FRAME_WIDTH = 32;
  const FRAME_HEIGHT = 32;
  const ANIMATION_SPEED = 100; // ms por frame
  const FRAMES_PER_ROW = 4;

  useEffect(() => {
    const image = new Image();
    image.src = spriteSheet;
    
    image.onload = () => {
      updateAnimation();
    };

    const updateAnimation = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const now = Date.now();
      if (isMoving && now - lastUpdateRef.current > ANIMATION_SPEED) {
        frameRef.current = (frameRef.current + 1) % FRAMES_PER_ROW;
        lastUpdateRef.current = now;
      }

      // Limpiar canvas
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Calcular fila de sprite basada en la dirección
      const rowIndex = {
        down: 0,
        left: 1,
        right: 2,
        up: 3
      }[direction];

      // Dibujar frame actual
      ctx.drawImage(
        image,
        frameRef.current * FRAME_WIDTH,
        rowIndex * FRAME_HEIGHT,
        FRAME_WIDTH,
        FRAME_HEIGHT,
        0,
        0,
        canvas.width,
        canvas.height
      );

      requestAnimationFrame(updateAnimation);
    };

    return () => {
      frameRef.current = 0;
    };
  }, [spriteSheet, isMoving, direction]);

  return (
    <canvas
      ref={canvasRef}
      width={FRAME_WIDTH * scale}
      height={FRAME_HEIGHT * scale}
      style={{
        position: 'absolute',
        left: position.x * (FRAME_WIDTH * scale),
        top: position.y * (FRAME_HEIGHT * scale),
        imageRendering: 'pixelated',
      }}
    />
  );
};

export default HeroSprite;
